"use client";
import { CodeBlock, CodeDiff } from "@ui/code-block";
import { Markdown } from "@ui/markdown";
import type { ArtifactDocument, ArtifactRevision } from "./artifact-types";
export function ArtifactContent({ artifact, revision, previous, view }: {
    artifact: ArtifactDocument;
    revision: ArtifactRevision;
    previous?: ArtifactRevision;
    view: "code" | "preview" | "changes";
}) {
    if (view === "preview" && artifact.kind === "markdown") {
        return <div className="mx-auto w-full max-w-3xl p-6"><Markdown text={revision.content}/></div>;
    }
    if (view === "changes" && previous) {
        return <div className="min-w-0 p-3"><CodeDiff oldFile={{ name: artifact.filename, contents: previous.content }} newFile={{ name: artifact.filename, contents: revision.content }} options={{ diffStyle: "unified" }}/></div>;
    }
    return <div className="min-w-0 p-3"><CodeBlock file={{ name: artifact.filename, contents: revision.content }} toolbar={false}/></div>;
}

import type { ArtifactDocument } from "./artifact-types";
/** Self-contained HTML fixture; the sandbox never receives workspace code or credentials. */
export function createPricingArtifactHtml(yearly = false, savings = false) {
    return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Simple pricing</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; font-family: ui-sans-serif, system-ui, sans-serif; color: #18181b; background: #fafafa; }
    main { max-width: 1080px; margin: 0 auto; padding: 64px 24px; }
    h1 { margin: 0; font-size: 36px; letter-spacing: -0.04em; text-align: center; }
    .lead { margin: 14px auto 36px; max-width: 480px; color: #71717a; text-align: center; line-height: 1.6; }
    .plans { display: grid; gap: 16px; grid-template-columns: repeat(auto-fit, minmax(min(100%, 200px), 1fr)); }
    .plan { display: flex; flex-direction: column; gap: 22px; padding: 24px; border: 1px solid #e4e4e7; border-radius: 16px; background: #fff; }
    .featured { border-color: #18181b; }
    .name { font-size: 14px; font-weight: 600; }
    .price { font-size: 36px; font-weight: 600; letter-spacing: -0.04em; }
    .price small { font-size: 13px; font-weight: 400; color: #71717a; letter-spacing: 0; }
    ul { margin: 0; padding: 0; list-style: none; display: grid; gap: 12px; color: #52525b; font-size: 13px; }
    li::before { content: "✓"; margin-right: 8px; color: #16a34a; }
    button { min-height: 40px; border: 0; border-radius: 10px; font: inherit; font-size: 13px; font-weight: 500; cursor: pointer; background: #f4f4f5; padding: 8px 14px; }
    button:focus-visible { outline: 2px solid #18181b; outline-offset: 3px; }
    .plan button { margin-top: auto; }
    .featured button { background: #18181b; color: #fff; }
    .billing { display: flex; justify-content: center; gap: 4px; margin-bottom: 36px; }
    .billing button[aria-pressed="true"] { background: #18181b; color: #fff; }
    .badge { display: inline-block; padding: 4px 8px; border-radius: 16px; color: #15803d; background: #f0fdf4; font-size: 11px; margin-left: 8px; }
    #notice { text-align: center; color: #52525b; min-height: 24px; font-size: 13px; margin-top: 24px; }
    @media (max-width: 480px) { main { padding: 36px 16px; } h1 { font-size: 30px; } }
  </style>
</head>
<body>
  <main>
    <h1>Simple pricing</h1>
    <p class="lead">Start free, upgrade when your team grows. Every plan includes unlimited projects.</p>
    ${yearly ? `<div class="billing" role="group" aria-label="Billing period">
      <button aria-pressed="true" onclick="billing(false, this)">Monthly</button>
      <button aria-pressed="false" onclick="billing(true, this)">Yearly · 2 months free</button>
    </div>` : ""}
    <section class="plans" aria-label="Pricing plans">
      <article class="plan">
        <div class="name">Hobby</div>
        <div class="price">$0 <small>/ month</small></div>
        <ul><li>3 members</li><li>1 GB storage</li><li>Community support</li></ul>
        <button onclick="choose('Hobby')">Get started</button>
      </article>
      <article class="plan featured">
        <div class="name">Team${savings ? '<span class="badge">Save 17% yearly</span>' : ""}</div>
        <div class="price"><span id="team-price">$24</span> <small>/ month</small></div>
        <ul><li>Unlimited members</li><li>100 GB storage</li><li>Priority support</li></ul>
        <button onclick="choose('Team')">Start a trial</button>
      </article>
      <article class="plan">
        <div class="name">Enterprise</div>
        <div class="price">Custom</div>
        <ul><li>SSO and audit logs</li><li>Unlimited storage</li><li>A named contact</li></ul>
        <button onclick="choose('Enterprise')">Talk to sales</button>
      </article>
    </section>
    <p id="notice" role="status"></p>
  </main>
  <script>
    function choose(plan) { document.getElementById('notice').textContent = plan + ' selected — preview only.'; }
    ${yearly ? `function billing(yearly, button) {
      document.getElementById('team-price').textContent = yearly ? '$20' : '$24';
      button.parentElement.querySelectorAll('button').forEach(function(item) { item.setAttribute('aria-pressed', String(item === button)); });
    }` : ""}
  </script>
</body>
</html>`;
}
export function createArtifactDemoDocuments(locale = "en"): ArtifactDocument[] {
    const zh = locale.startsWith("zh");
    return [
        { id: "pricing", title: zh ? "定价页面" : "Pricing page", filename: "pricing-page.html", kind: "html", revisions: [{ id: "pricing-v1", content: createPricingArtifactHtml() }] },
        { id: "launch", title: zh ? "发布计划" : "Launch plan", filename: "launch-plan.md", kind: "markdown", revisions: [{ id: "launch-v1", content: zh ? `# 发布计划\n\n让团队从首次体验走向持续使用。\n\n## 发布目标\n\n- 验证定价与产品定位\n- 收集首批团队的使用反馈\n- 建立可持续的支持流程\n\n## 时间安排\n\n| 阶段 | 工作 | 交付物 |\n| --- | --- | --- |\n| 准备 | 内测与性能检查 | 发布清单 |\n| 发布 | 产品介绍与演示 | 产品页面 |\n| 跟进 | 反馈访谈与迭代 | 改进计划 |\n\n## 发布前检查\n\n- [x] 定价页可在移动端使用\n- [x] 月付和年付价格明确\n- [ ] 完成首批用户访谈\n\n> 先观察用户完成首次任务，再决定下一轮优化。` : `# Launch plan\n\nHelp teams move from their first session to everyday use.\n\n## Goals\n\n- Validate pricing and positioning\n- Learn from the first teams\n- Build a sustainable support workflow\n\n## Timeline\n\n| Phase | Work | Deliverable |\n| --- | --- | --- |\n| Prepare | Private beta and performance checks | Release checklist |\n| Launch | Product story and walkthrough | Product page |\n| Follow up | Interviews and improvements | Iteration plan |\n\n## Before launch\n\n- [x] Check mobile pricing\n- [x] Explain monthly and yearly billing\n- [ ] Interview the first teams\n\n> Watch people complete their first task before choosing the next improvement.` }] },
        { id: "debounce", title: zh ? "Debounce Hook" : "Debounce hook", filename: "use-debounce.ts", kind: "code", revisions: [{ id: "debounce-v1", content: `import { useEffect, useState } from "react";\n\n/** Update a value after input has settled. */\nexport function useDebounce<T>(value: T, delay = 300): T {\n  const [debounced, setDebounced] = useState(value);\n\n  useEffect(() => {\n    const timer = setTimeout(() => setDebounced(value), delay);\n    return () => clearTimeout(timer);\n  }, [value, delay]);\n\n  return debounced;\n}\n` }] },
    ];
}

import type { ArtifactPreviewLabels } from "./artifact-types";
export const artifactPreviewEnLabels: ArtifactPreviewLabels = {
    panel: "Artifact preview", code: "Code", preview: "Preview", changes: "Changes", versions: "Version history",
    version: (index, count) => `Version ${index} of ${count}`, latest: "Latest", restore: "Restore this version",
    restoring: "Restoring…", restoreFailed: "Could not restore this version. Try again.", writing: "Writing…", ready: "Ready",
    stopped: "Generation stopped", failed: "Could not display this content.", retry: "Retry", copy: "Copy code", copied: "Copied",
    copyFailed: "Could not copy. Try again.", download: "Download", downloadFailed: "Could not download. Try again.",
    refresh: "Reload preview", expand: "Expand preview", collapse: "Exit full screen", expandFailed: "Full screen is unavailable.",
    close: "Close preview", empty: "Your next idea starts here", emptyDescription: "Open an artifact from the conversation to preview it.",
    loading: "Loading content…", lines: (count) => `${count} lines`,
};
export const artifactPreviewZhLabels: ArtifactPreviewLabels = {
    panel: "生成内容预览", code: "代码", preview: "预览", changes: "变更", versions: "版本历史",
    version: (index, count) => `第 ${index} 版，共 ${count} 版`, latest: "最新", restore: "恢复此版本",
    restoring: "恢复中…", restoreFailed: "未能恢复此版本，请重试。", writing: "正在生成…", ready: "已就绪",
    stopped: "已停止生成", failed: "未能显示内容。", retry: "重试", copy: "复制代码", copied: "已复制",
    copyFailed: "复制失败，请重试。", download: "下载", downloadFailed: "下载失败，请重试。",
    refresh: "刷新预览", expand: "展开预览", collapse: "退出全屏", expandFailed: "当前无法进入全屏。",
    close: "关闭预览", empty: "让想法在这里成形", emptyDescription: "从对话中打开生成内容，即可在此预览。",
    loading: "正在加载内容…", lines: (count) => `${count} 行`,
};
export function resolveArtifactPreviewLabels(locale?: string, labels?: Partial<ArtifactPreviewLabels>) {
    return { ...(locale?.startsWith("zh") ? artifactPreviewZhLabels : artifactPreviewEnLabels), ...labels };
}

"use client";
import { Component, lazy, Suspense, useEffect, useRef, useState, type ReactNode } from "react";
import { Button } from "@ui/button";
import { DropdownContent, DropdownMenu, DropdownTrigger } from "@ui/dropdown";
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from "@ui/empty";
import { InlineNotice, InlineNoticeContent } from "@ui/inline-notice";
import { MenuItem } from "@ui/menu-item";
import { Tabs, TabsList, TabItem, TabPanel } from "@ui/tabs";
import { useIcon } from "@lib/icon-context";
import { cn } from "@lib/utils";
import { resolveArtifactPreviewLabels } from "./artifact-labels";
import type { ArtifactDocument, ArtifactPreviewLabels, ArtifactPreviewPanelProps, ArtifactRevision } from "./artifact-types";
const Content = lazy(() => import("./artifact-content").then((module) => ({ default: module.ArtifactContent })));
class PreviewBoundary extends Component<{
    children: ReactNode;
    fallback: ReactNode;
}, {
    failed: boolean;
}> {
    state = { failed: false };
    static getDerivedStateFromError() { return { failed: true }; }
    render() { return this.state.failed ? this.props.fallback : this.props.children; }
}
function RevisionSurface({ artifact, revision, previous, labels, restoring, onRestore, onRetry }: {
    artifact: ArtifactDocument;
    revision: ArtifactRevision;
    previous?: ArtifactRevision;
    labels: ArtifactPreviewLabels;
    restoring: boolean;
    onRestore?: () => void;
    onRetry?: () => void;
}) {
    const [view, setView] = useState("preview");
    const [refresh, setRefresh] = useState(0);
    const [notice, setNotice] = useState("");
    const [copying, setCopying] = useState(false);
    const copyLock = useRef(false);
    const mounted = useRef(true);
    useEffect(() => { mounted.current = true; return () => { mounted.current = false; }; }, []);
    const Copy = useIcon("copy");
    const Download = useIcon("arrow-down");
    const Refresh = useIcon("rotate-ccw");
    const streaming = revision.status === "streaming";
    const failed = revision.status === "error";
    const canPreview = artifact.kind !== "code";
    const activeView = streaming || failed || !canPreview && view === "preview" ? "code" : view;
    const [visitedViews, setVisitedViews] = useState<string[]>([]);
    useEffect(() => {
        setVisitedViews((current) => current.includes(activeView) ? current : [...current, activeView]);
    }, [activeView]);
    const copy = async () => {
        if (copyLock.current)
            return;
        copyLock.current = true;
        setCopying(true);
        try {
            await navigator.clipboard.writeText(revision.content);
            if (mounted.current)
                setNotice(labels.copied);
        }
        catch {
            if (mounted.current)
                setNotice(labels.copyFailed);
        }
        finally {
            copyLock.current = false;
            if (mounted.current)
                setCopying(false);
        }
    };
    const download = () => {
        try {
            const type = artifact.kind === "html" ? "text/html" : artifact.kind === "markdown" ? "text/markdown" : "text/plain";
            const url = URL.createObjectURL(new Blob([revision.content], { type: `${type};charset=utf-8` }));
            const link = document.createElement("a");
            link.href = url;
            link.download = artifact.filename;
            link.click();
            setTimeout(() => URL.revokeObjectURL(url), 1000);
        }
        catch {
            setNotice(labels.downloadFailed);
        }
    };
    return <>
    <Tabs value={activeView} onValueChange={setView} variant="segment" color="neutral" className="flex min-h-0 flex-1 flex-col">
      <div className="flex shrink-0 flex-wrap items-center justify-between gap-2 border-b-hairline border-border px-3 py-2">
        <TabsList aria-label={artifact.title}>
          <TabItem value="code" label={labels.code}/>
          {canPreview && <TabItem value="preview" label={labels.preview} disabled={streaming || failed}/>}
          {previous && <TabItem value="changes" label={labels.changes} disabled={streaming || failed}/>}
        </TabsList>
        <div className="flex items-center gap-1">
          {canPreview && <Button size="sm" variant="ghost" iconOnly aria-label={labels.refresh} disabled={streaming || failed || activeView !== "preview"} onClick={() => setRefresh((value) => value + 1)}><Refresh aria-hidden/></Button>}
          <Button size="sm" variant="ghost" iconOnly aria-label={labels.copy} disabled={streaming || failed || copying} onClick={() => void copy()}><Copy aria-hidden/></Button>
          <Button size="sm" variant="ghost" iconOnly aria-label={`${labels.download} ${artifact.filename}`} disabled={streaming || failed} onClick={download}><Download aria-hidden/></Button>
        </div>
      </div>
      {notice && <p role="status" className="px-4 py-2 text-label text-fg-muted">{notice}</p>}
      {failed ? <div className="p-4"><InlineNotice><InlineNoticeContent><span role="alert">{revision.error ?? labels.failed}</span>{onRetry && <Button size="sm" variant="ghost" onClick={onRetry}>{labels.retry}</Button>}</InlineNoticeContent></InlineNotice></div> :
            (["code", "preview", "changes"] as const).filter((item) => item === "code" || item === "preview" && canPreview || item === "changes" && previous).map((item) => <TabPanel key={item} value={item} keepMounted className={cn("min-h-0 min-w-0 flex-1 overflow-auto", activeView !== item && "hidden")}>
          {(!streaming || item === "code") && (activeView === item || visitedViews.includes(item)) && <PreviewBoundary key={item === "preview" ? refresh : 0} fallback={<div className="p-4" role="alert">{labels.failed}</div>}>
            {item === "preview" && artifact.kind === "html" ? <iframe title={`${artifact.title} — ${labels.preview}`} srcDoc={revision.content} sandbox="allow-scripts" referrerPolicy="no-referrer" className="block size-full border-0 bg-surface-floating"/> :
                        <Suspense fallback={<p role="status" className="p-4 text-body text-fg-muted">{labels.loading}</p>}><Content artifact={artifact} revision={revision} previous={previous} view={item}/></Suspense>}
          </PreviewBoundary>}
        </TabPanel>)}
    </Tabs>
    <div className="flex shrink-0 flex-wrap items-center justify-between gap-2 border-t-hairline border-border px-4 py-2 text-label text-fg-muted">
      <span role="status">{streaming ? labels.writing : failed ? labels.failed : labels.ready} · {labels.lines(revision.content ? revision.content.split("\n").length : 0)}</span>
      {onRestore && <Button size="sm" variant="secondary" loading={restoring} disabled={streaming || failed} onClick={onRestore}>{restoring ? labels.restoring : labels.restore}</Button>}
    </div>
  </>;
}
export function ArtifactPreviewPanel({ artifact, revisionId, onRevisionChange, onRestore, onRetry, onClose, locale, labels: overrides, className, ...props }: ArtifactPreviewPanelProps) {
    const labels = resolveArtifactPreviewLabels(locale, overrides);
    const [selected, setSelected] = useState<{
        documentId: string;
        revisionId: string;
    } | null>(null);
    const latest = artifact?.revisions.at(-1);
    const requested = revisionId ?? (selected?.documentId === artifact?.id ? selected?.revisionId : undefined);
    const revision = artifact?.revisions.find((item) => item.id === requested) ?? latest;
    const index = artifact?.revisions.findIndex((item) => item === revision) ?? -1;
    const root = useRef<HTMLElement>(null);
    const restoreLock = useRef(false);
    const [restoring, setRestoring] = useState(false);
    const [restoreError, setRestoreError] = useState<{
        key: string;
        text: string;
    } | null>(null);
    const [fullscreen, setFullscreen] = useState(false);
    const [fullscreenError, setFullscreenError] = useState(false);
    const Down = useIcon("chevron-down");
    const Close = useIcon("x");
    const Expand = useIcon("monitor");
    const currentKey = JSON.stringify([artifact?.id, revision?.id]);
    useEffect(() => { setSelected(null); }, [artifact?.id]);
    useEffect(() => {
        const update = () => setFullscreen(document.fullscreenElement === root.current);
        document.addEventListener("fullscreenchange", update);
        return () => document.removeEventListener("fullscreenchange", update);
    }, []);
    const select = (id: string) => {
        if (revisionId === undefined && artifact)
            setSelected({ documentId: artifact.id, revisionId: id });
        onRevisionChange?.(id);
    };
    const restore = async () => {
        if (!artifact || !revision || !onRestore || restoreLock.current)
            return;
        restoreLock.current = true;
        setRestoring(true);
        setRestoreError(null);
        try {
            await onRestore(artifact, revision);
            if (revisionId === undefined)
                setSelected((current) => current?.documentId === artifact.id && current.revisionId === revision.id ? null : current);
        }
        catch {
            setRestoreError({ key: currentKey, text: labels.restoreFailed });
        }
        finally {
            restoreLock.current = false;
            setRestoring(false);
        }
    };
    const expand = async () => {
        setFullscreenError(false);
        try {
            if (document.fullscreenElement === root.current)
                await document.exitFullscreen();
            else
                await root.current?.requestFullscreen();
        }
        catch {
            setFullscreenError(true);
        }
    };
    const close = async () => {
        if (document.fullscreenElement === root.current)
            await document.exitFullscreen().catch(() => { });
        onClose?.();
    };
    return <section {...props} ref={root} aria-label={props["aria-label"] ?? labels.panel} data-slot="artifact-panel" data-artifact-kind="generated" className={cn("flex size-full min-h-0 min-w-0 flex-col overflow-hidden bg-surface-floating text-fg-default", className)}>
    <div className="flex shrink-0 flex-wrap items-center gap-2 border-b-hairline border-border px-4 py-2">
      <div className="min-w-0 flex-1"><h2 className="truncate text-label font-medium" title={artifact?.title}>{artifact?.title ?? labels.panel}</h2>{artifact && <p className="truncate font-mono text-label text-fg-muted" title={artifact.filename}>{artifact.filename}</p>}</div>
      {artifact && revision && <DropdownMenu>
        <DropdownTrigger render={<Button size="sm" variant="ghost" trailingIcon={Down} aria-label={labels.version(index + 1, artifact.revisions.length)}>v{index + 1}</Button>}/>
        <DropdownContent align="end" aria-label={labels.versions} checkedIndex={index}>{artifact.revisions.map((item, position) => <MenuItem key={item.id} index={position} label={item.label ?? `v${position + 1}`} trailing={position === artifact.revisions.length - 1 ? <span className="text-label text-fg-muted">{labels.latest}</span> : undefined} checked={item.id === revision.id} onSelect={() => select(item.id)}/>)}</DropdownContent>
      </DropdownMenu>}
      <Button size="sm" variant="ghost" iconOnly aria-label={fullscreen ? labels.collapse : labels.expand} onClick={() => void expand()}><Expand aria-hidden/></Button>
      {onClose && <Button size="sm" variant="ghost" iconOnly aria-label={labels.close} onClick={() => void close()}><Close aria-hidden/></Button>}
    </div>
    {fullscreenError && <p role="alert" className="px-4 py-2 text-label text-fg-danger">{labels.expandFailed}</p>}
    {restoreError?.key === currentKey && <p role="alert" className="px-4 py-2 text-label text-fg-danger">{restoreError.text}</p>}
    {artifact && revision ? <RevisionSurface key={currentKey} artifact={artifact} revision={revision} previous={artifact.revisions[index - 1]} labels={labels} restoring={restoring} onRestore={onRestore && revision !== latest ? () => void restore() : undefined} onRetry={onRetry ? () => onRetry(artifact, revision) : undefined}/> :
            <div className="flex flex-1 items-center justify-center p-6"><Empty reason="first-use" scope="inline" density="compact"><EmptyHeader><EmptyTitle>{labels.empty}</EmptyTitle><EmptyDescription>{labels.emptyDescription}</EmptyDescription></EmptyHeader></Empty></div>}
  </section>;
}

import type { HTMLAttributes } from "react";
import type { ChatWorkspaceProps } from "@components/blocks/chat-workspace-01";
export interface ArtifactRevision {
    /** Stable within a document. Append a new ID for each revision. */
    id: string;
    content: string;
    label?: string;
    status?: "ready" | "streaming" | "error";
    error?: string;
}
export interface ArtifactDocument {
    id: string;
    title: string;
    filename: string;
    kind: "html" | "markdown" | "code";
    /** Oldest first. Content and history are owned by the host. */
    revisions: readonly ArtifactRevision[];
}
export interface ArtifactPreviewLabels {
    panel: string;
    code: string;
    preview: string;
    changes: string;
    versions: string;
    version: (index: number, count: number) => string;
    latest: string;
    restore: string;
    restoring: string;
    restoreFailed: string;
    writing: string;
    ready: string;
    stopped: string;
    failed: string;
    retry: string;
    copy: string;
    copied: string;
    copyFailed: string;
    download: string;
    downloadFailed: string;
    refresh: string;
    expand: string;
    collapse: string;
    expandFailed: string;
    close: string;
    empty: string;
    emptyDescription: string;
    loading: string;
    lines: (count: number) => string;
}
export interface ArtifactPreviewPanelProps extends Omit<HTMLAttributes<HTMLElement>, "children"> {
    artifact: ArtifactDocument | null;
    revisionId?: string;
    onRevisionChange?: (revisionId: string) => void;
    /** Persist by appending a new revision. Uncontrolled selection follows it after success unless the user navigated elsewhere. */
    onRestore?: (artifact: ArtifactDocument, revision: ArtifactRevision) => void | Promise<void>;
    onRetry?: (artifact: ArtifactDocument, revision: ArtifactRevision) => void;
    onClose?: () => void;
    locale?: string;
    labels?: Partial<ArtifactPreviewLabels>;
}
export interface ArtifactWorkspaceProps extends Omit<ChatWorkspaceProps, "artifacts"> {
    artifact: ArtifactDocument | null;
    previewProps?: Omit<ArtifactPreviewPanelProps, "artifact" | "locale">;
}

"use client";
import { ArtifactCard, ChatWorkspace, type ArtifactResource } from "@components/blocks/chat-workspace-01";
import { ArtifactPreviewPanel } from "./artifact-preview-panel";
import { resolveArtifactPreviewLabels } from "./artifact-labels";
import type { ArtifactDocument, ArtifactWorkspaceProps } from "./artifact-types";
export function ArtifactWorkspace({ artifact, previewProps, ...props }: ArtifactWorkspaceProps) {
    return <ChatWorkspace {...props} artifacts={<ArtifactPreviewPanel {...previewProps} artifact={artifact} locale={props.locale}/>}/>;
}
/** Uses the same resource card as ChatWorkspace, preserving its button and file contracts. */
export function GeneratedArtifactCard({ artifact, revisionId, onOpen, locale }: {
    artifact: ArtifactDocument;
    revisionId?: string;
    onOpen: (artifact: ArtifactDocument, revisionId: string) => void;
    locale?: string;
}) {
    const revision = artifact.revisions.find((item) => item.id === revisionId) ?? artifact.revisions.at(-1);
    if (!revision)
        return null;
    const index = artifact.revisions.indexOf(revision) + 1;
    const labels = resolveArtifactPreviewLabels(locale);
    const resource: ArtifactResource = { id: artifact.id, version: revision.id, name: artifact.filename, content: revision.content, kind: artifact.kind === "markdown" ? "markdown" : "code" };
    return <ArtifactCard locale={locale} title={`${artifact.title} · ${revision.status === "streaming" ? labels.writing : `v${index}`}`} resources={[resource]} onOpen={() => onOpen(artifact, revision.id)}/>;
}

